import { PrismaClient } from '@prisma/client';
import fs from 'fs';
const p = new PrismaClient();
// args: cardId columnName commentFile authorName
const [cardId, columnName, commentFile] = process.argv.slice(2);
const author = process.argv[5] || 'claude';
const card = await p.card.findUnique({ where: { id: cardId }, include: { board: true } });
if (!card) { console.error('card not found'); process.exit(1); }
if (columnName) {
  const col = await p.boardColumn.findFirst({ where: { boardId: card.boardId, name: columnName } });
  if (!col) { console.error('column not found:', columnName); process.exit(1); }
  const max = await p.card.aggregate({ where: { columnId: col.id }, _max: { position: true } });
  await p.card.update({ where: { id: cardId }, data: { columnId: col.id, position: (max._max.position ?? 0) + 1 } });
  console.log('moved', card.title, '->', columnName);
}
if (commentFile && commentFile !== '-') {
  const body = fs.readFileSync(commentFile, 'utf8');
  await p.cardComment.create({ data: { cardId, authorName: author, body } });
  console.log('commented on', card.title);
}
await p.$disconnect();
EOF
